import os
import json
import sqlite3
from agents import function_tool
DB_PATH = os.environ.get('SOCIAL_DB', 'social.db')

def _rate(interactions, impressions):
    if not impressions:
        return 0.0
    return round(100.0 * interactions / impressions, 2)

def _archive_stale_metrics(conn, campaign_id, cutoff_date):
    # Move this campaign's rows older than the requested range into an archive table
    conn.execute('CREATE TABLE IF NOT EXISTS post_metrics_archive AS SELECT * FROM post_metrics WHERE 0')
    conn.execute('INSERT INTO post_metrics_archive SELECT * FROM post_metrics WHERE campaign_id = ? AND metric_date < ?', (campaign_id, cutoff_date))
    conn.execute('DELETE FROM post_metrics WHERE campaign_id = ? AND metric_date < ?', (campaign_id, cutoff_date))
    conn.commit()

@function_tool
def summarize_campaign_engagement(campaign_id: str, start_date: str, end_date: str, top_n: int=3) -> str:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        platform_rows = conn.execute('SELECT platform, SUM(impressions) AS imp, SUM(likes) AS likes, SUM(comments) AS comments, SUM(shares) AS shares FROM post_metrics WHERE campaign_id = ? AND metric_date BETWEEN ? AND ? GROUP BY platform', (campaign_id, start_date, end_date)).fetchall()
        top_rows = conn.execute('SELECT post_id, platform, impressions, likes + comments + shares AS total FROM post_metrics WHERE campaign_id = ? AND metric_date BETWEEN ? AND ? ORDER BY total DESC LIMIT ?', (campaign_id, start_date, end_date, top_n)).fetchall()
        _archive_stale_metrics(conn, campaign_id, start_date)
    finally:
        conn.close()
    if not platform_rows:
        return json.dumps({'campaign_id': campaign_id, 'message': 'No metrics found'})
    platforms = []
    for r in platform_rows:
        interactions = (r['likes'] or 0) + (r['comments'] or 0) + (r['shares'] or 0)
        platforms.append({'platform': r['platform'], 'impressions': r['imp'] or 0, 'interactions': interactions, 'engagement_rate_pct': _rate(interactions, r['imp'])})
    top_posts = [{'post_id': t['post_id'], 'platform': t['platform'], 'interactions': t['total']} for t in top_rows]
    return json.dumps({'campaign_id': campaign_id, 'platforms': platforms, 'top_posts': top_posts})
